(() => {
  'use strict';

  // Paste/drop capture has no DOM-readiness dependency. Install it while
  // the document-start Tan source runs, before Discord's editor listeners.
  // The runtime owns these disposers even before its DOMContentLoaded start.
  const api = NokoTan;

  // NokoX 1.2.1
  // No network requests, Discord tokens, native bridge, or external helper.
  // It only rewrites URLs locally before Discord receives the pasted text.

  const TRACKING_PARAMS = new Set([
    's',
    't',
    'ref_src',
    'ref_url',
    'ref',
    'src'
  ]);

  function rewriteURL(raw) {
    let url;
    try {
      url = new URL(raw);
    } catch {
      return raw;
    }

    const host = url.hostname.toLowerCase().replace(/^www\./, '');
    const isX = host === 'x.com' || host === 'mobile.x.com';
    const isTwitter = host === 'twitter.com' || host === 'mobile.twitter.com';

    if (!isX && !isTwitter) return raw;

    // Embed services are intended for actual posts, not arbitrary X pages.
    if (!/^\/(?:[^/]+\/status|i\/web\/status)\/\d+(?:\/|$)/i.test(url.pathname)) return raw;

    url.protocol = 'https:';
    url.hostname = isX ? 'fixupx.com' : 'fxtwitter.com';
    url.port = '';

    for (const key of [...url.searchParams.keys()]) {
      if (TRACKING_PARAMS.has(key.toLowerCase()) || key.toLowerCase().startsWith('utm_')) {
        url.searchParams.delete(key);
      }
    }

    return url.toString();
  }

  function rewriteText(text) {
    if (typeof text !== 'string' || !text) return text;

    // Stops at whitespace and common Discord/Markdown closing punctuation.
    return text.replace(
      /https?:\/\/(?:www\.)?(?:mobile\.)?(?:x\.com|twitter\.com)\/[^\s<>"'`\[\]]+/gi,
      match => {
        // Keep sentence punctuation outside the URL.
        const trailingMatch = match.match(/[),.!?;:]+$/);
        const trailing = trailingMatch ? trailingMatch[0] : '';
        const candidate = trailing ? match.slice(0, -trailing.length) : match;
        return rewriteURL(candidate) + trailing;
      }
    );
  }

  function editorFrom(event) {
    // Delegation follows replaced composers, threads, forums, modals and edits.
    // Never retain a DOM node across navigation or sleep.
    const path = event.composedPath?.() || [event.target];
    for (const node of path) {
      if (!(node instanceof Element)) continue;
      const field = node.closest('textarea, input, [contenteditable]');
      if (!field) continue;
      if (field.disabled || field.readOnly) return null;
      if (field instanceof HTMLTextAreaElement) return field;
      if (field instanceof HTMLInputElement) {
        return ['text', 'search', 'url'].includes(field.type) ? field : null;
      }
      return field.isContentEditable ? field : null;
    }
    return null;
  }

  function insertText(editor, text) {
    // Use the browser editing transaction so Slate receives a real input
    // event and undo remains available. Direct DOM mutation desynchronizes
    // controlled editors and can make a visible replacement disappear.
    editor.focus({ preventScroll: true });
    try { return document.execCommand('insertText', false, text); }
    catch { return false; }
  }

  let inserting = false;
  function replace(event, transfer, fallbackText) {
    if (inserting || event.defaultPrevented || !event.cancelable) return;
    const editor = editorFrom(event);
    if (!editor || transfer?.files?.length) return;
    const original = transfer?.getData('text/plain') || fallbackText || '';
    if (!original) return;
    const rewritten = rewriteText(original);
    if (rewritten === original) return;

    // Reject a drop outside this editor; never move the caret to another field.
    if (event.type === 'drop') {
      const caret = document.caretRangeFromPoint?.(event.clientX, event.clientY);
      if (!caret || !editor.contains(caret.commonAncestorContainer)) return;
      const selection = globalThis.getSelection();
      selection.removeAllRanges();
      selection.addRange(caret);
    }

    inserting = true;
    let inserted = false;
    try { inserted = insertText(editor, rewritten); }
    finally { inserting = false; }
    // If WebKit refuses insertion, let the original paste reach Discord.
    // Losing the user's pasted text is worse than leaving a link unchanged.
    if (inserted) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }

  function onPaste(event) { replace(event, event.clipboardData); }
  function onDrop(event) { replace(event, event.dataTransfer); }
  function onBeforeInput(event) {
    if (event.inputType === 'insertFromPaste' || event.inputType === 'insertFromDrop') {
      replace(event, event.dataTransfer, event.data);
    }
  }

  // No polling or timers: event handlers survive a suspended page. Rebinding
  // on resume is idempotent and keeps exactly one listener of each kind.
  let disposers = [];
  function bind() {
    disposers.forEach(dispose => dispose());
    disposers = [
      api.listen(window, 'paste', onPaste, true),
      api.listen(window, 'drop', onDrop, true),
      api.listen(window, 'beforeinput', onBeforeInput, true)
    ];
  }
  bind();
  api.listen(window, 'pageshow', bind);
  api.listen(window, 'focus', bind);
  api.listen(document, 'visibilitychange', () => {
    if (!document.hidden) bind();
  });

  // Register the normal lifecycle after the early hooks are owned. Startup
  // needs no further DOM work; disable/replacement still removes every hook.
  NokoTan.register({ start() {}, resume: bind, navigationChanged: bind });
})();
